std::vector<std::pair<size_t, size_t>> result;
size_t const size = boxes.size();
for (size_t i = 0; i < size; ++i)
{
    BasicTypesXYZ::BoundingBox3D const& boxA = boxes[i];
    for (size_t j = i + 1; j < size; ++j)
    {
        BasicTypesXYZ::BoundingBox3D const& boxB = boxes[j];
        if (boxA.Max.x >= boxB.Min.x && boxA.Min.x <= boxB.Max.x &&
            boxA.Max.y >= boxB.Min.y && boxA.Min.y <= boxB.Max.y &&
            boxA.Max.z >= boxB.Min.z && boxA.Min.z <= boxB.Max.z)
        {
            result.emplace_back(i, j);
        }
    }
}
return result;

